<form class="card max-w-4xl space-y-5 p-6" method="post" enctype="multipart/form-data" action="<?=url('payables/save')?>"><?=csrf_field()?><input type="hidden" name="id" value="<?=e($item['id'])?>"><div class="grid gap-4 sm:grid-cols-2"><label class="sm:col-span-2"><span class="label">Descrição</span><input class="field" name="description" value="<?=e($item['description'])?>" required></label><label><span class="label">Fornecedor</span><select class="field" name="contact_id"><option value="">Selecione</option><?php foreach($contacts as $o):?><option value="<?=$o['id']?>" <?=$item['contact_id']==$o['id']?'selected':''?>><?=e($o['name'])?></option><?php endforeach;?></select></label><label><span class="label">Categoria</span><select class="field" name="category_id"><option value="">Selecione</option><?php foreach($categories as $o):?><option value="<?=$o['id']?>" <?=$item['category_id']==$o['id']?'selected':''?>><?=e($o['name'])?></option><?php endforeach;?></select></label><label><span class="label">Valor</span><input class="field" name="amount" inputmode="decimal" value="<?=e($item['amount'])?>" placeholder="0,00" required></label><label><span class="label">Data de vencimento</span><input class="field" type="date" name="due_date" value="<?=e($item['due_date'])?>" required></label><label><span class="label">Forma de pagamento</span><select class="field" name="payment_method"><?php foreach(['pix'=>'Pix','boleto'=>'Boleto','cartao'=>'Cartão','dinheiro'=>'Dinheiro','debito_automatico'=>'Débito automático','transferencia'=>'Transferência'] as $v=>$l):?><option value="<?=$v?>" <?=$item['payment_method']===$v?'selected':''?>><?=$l?></option><?php endforeach;?></select></label><label><span class="label">Recorrência</span><select class="field" name="recurrence"><?php foreach(['nenhuma'=>'Nenhuma','mensal'=>'Mensal','quinzenal'=>'Quinzenal','semanal'=>'Semanal'] as $v=>$l):?><option value="<?=$v?>" <?=$item['recurrence']===$v?'selected':''?>><?=$l?></option><?php endforeach;?></select></label><label class="sm:col-span-2"><span class="label">Comprovante (PDF ou imagem, até 5 MB)</span><input class="field" type="file" name="attachment" accept="application/pdf,image/jpeg,image/png,image/webp"></label><label class="sm:col-span-2"><span class="label">Observações</span><textarea class="field" name="notes" rows="4"><?=e($item['notes'])?></textarea></label></div><div class="flex gap-3"><button class="btn btn-primary">Salvar</button><a class="btn btn-light" href="<?=url('payables')?>">Cancelar</a></div></form>
